namespace bgiplayer {
ArchiveSet::ArchiveSet(std::filesystem::path game_root)
    : game_root_(std::move(game_root)) {
    if (!host_files::is_directory(game_root_)) {
        throw Error("game directory does not exist: " + game_root_.string());
    }
    std::error_code error;
    for (const auto& entry : host_files::entries(game_root_, true, error)) {
        if (!entry.regular) continue;
        const auto extension = ascii_lower(entry.path.extension().string());
        if (extension != ".arc") {
            continue;
        }
        try {
            Archive archive = Archive::open(entry.path);
            const auto key = archive_key(entry.path.filename().string());
            by_archive_.try_emplace(key, archives_.size());
            archives_.push_back(std::move(archive));
        } catch (const Error&) {
            // Some games contain non-BGI *.arc files. Ignore unknown containers.
        }
    }
}
}  // namespace bgiplayer
